// VEYA-AI plugin: Quote of the Day
// Shows an AI-generated motivational quote once per day

module.exports = {
  onLoad: async () => {
    // Already shown today?
    const today = new Date().toDateString();
    if (VEYA.storage.get('lastQuoteDate') === today) {
      const saved = VEYA.storage.get('todayQuote');
      if (saved) {
        console.log('[Quote of the Day]', saved);
        return;
      }
    }

    // Ask the AI for a new quote
    const quote = await VEYA.ai.ask(
      'Give me a short motivational quote for today. Two sentences max.',
      'You are a motivating coach.'
    );

    VEYA.storage.set('todayQuote', quote);
    VEYA.storage.set('lastQuoteDate', today);
    console.log('[Quote of the Day]', quote);
  },

  onUnload: () => {
    console.log('[Quote of the Day] Disabled.');
  }
};
